import sys


def cross(o, a, b):
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])


def intersect(p1, p2, p3, p4):
    d1 = cross(p3, p4, p1)
    d2 = cross(p3, p4, p2)
    d3 = cross(p1, p2, p3)
    d4 = cross(p1, p2, p4)
    return (d1 > 0) != (d2 > 0) and (d3 > 0) != (d4 > 0)


def main():
    data = sys.stdin.read().split()
    r, b = int(data[0]), int(data[1])
    vals = list(map(int, data[2:]))
    ships = [(vals[2 * i], vals[2 * i + 1]) for i in range(r)]
    bases = [(vals[2 * (r + i)], vals[2 * (r + i) + 1]) for i in range(b)]
    if r != b:
        print("No")
        return
    used = [False] * b
    chosen = []

    def rec(i):
        if i == r:
            return True
        for j in range(b):
            if used[j]:
                continue
            seg = (ships[i], bases[j])
            ok = True
            for (s, t) in chosen:
                if intersect(seg[0], seg[1], s, t):
