from collections import deque


def main():
    n, m = map(int, sys.stdin.read().split())
    if n >= m:
        print(n - m)
        return
    limit = m + m // 5
    dist = {n: 0}
    q = deque([n])
    while q:
        v = q.popleft()
        if v == m:
            break
        for w in (v * 2, v - 1):
            if 0 < w <= limit and w not in dist:
                dist[w] = dist[v] + 1
                q.append(w)
    print(dist.get(m, m - n))


