def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    k = int(data[1])
    temps = [int(x) for x in data[2:2 + n]]
    neg = sum(1 for t in temps if t < 0)
    if neg == 0:
        print(0)
        return
    if neg > k:
        print(-1)
        return
    rest = k - neg
    first = 0
    while temps[first] >= 0:
        first += 1
    last = n - 1
    while temps[last] >= 0:
        last -= 1
    trailing = n - 1 - last
    gaps = []
    run = 0
    groups = 1
    for i in range(first, last + 1):
        if temps[i] >= 0:
            run += 1
        else:
            if run:
                gaps.append(run)
                groups += 1
                run = 0
    gaps.sort()
    changes = 2 * groups
    for g in gaps:
        if rest >= g:
            rest -= g
            changes -= 2
        else:
            break
    if trailing > 0:
        if rest > trailing:
            changes -= 1
    else:
        changes -= 1
    print(changes)


main()

